示意1 - 顶点拖拽伪代码：
onPointerDown(vertexId){ setActiveVertex(vertexId); }
onPointerMove(e){ if(!active) return; newPos = mapClientToSvg(e); if(snap) newPos = snapToGrid(newPos); updateVertex(active, newPos); debounce(calcArea,100); }
onPointerUp(){ validateTriangle(); pushHistory(); clearActive(); }

